     3→import React, { createContext, useContext, useState, useCallback, useRef, useEffect } from 'react';
     4→import { Toast, ToastContainer } from '@/components/ui/toast';
     5→
     6→/**
     7→ * Toast Notification Provider
     8→ *
     9→ * Provides global toast notification management across the application.
    10→ * Supports creating, displaying, and auto-dismissing toast notifications.
    11→ *
    12→ * @example
    13→ * ```tsx
    14→ * // In your app root
    15→ * <ToastProvider>
    16→ *   <YourApp />
    17→ * </ToastProvider>
    18→ *
    19→ * // In any component
    20→ * const { showToast } = useToast();
    21→ * showToast('Success!', 'success');
    22→ * ```
    23→ */
    24→
    25→// Toast data structure
    26→export interface ToastData {
    27→  /** Unique identifier for the toast */
    28→  id: string;
    29→  /** Toast variant/type */
    30→  variant: 'success' | 'error' | 'warning' | 'info';
    31→  /** Main message to display */
    32→  message: string;
    33→  /** Optional title */
    34→  title?: string;
    35→  /** Duration in milliseconds before auto-dismiss */
    36→  duration?: number;
    37→}
    38→
    39→// Options when creating a toast
    40→export interface ShowToastOptions {
    41→  /** Optional title for the toast */
    42→  title?: string;
    43→  /** Duration in milliseconds (default: 4000ms) */
    44→  duration?: number;
    45→}
    46→
    47→// Context value interface
    48→interface ToastContextValue {
    49→  /** Display a new toast notification */
    50→  showToast: (
    51→    message: string,
    52→    variant: 'success' | 'error' | 'warning' | 'info',
    53→    options?: ShowToastOptions
    54→  ) => void;
    55→  /** Remove a specific toast by ID */
    56→  removeToast: (id: string) => void;
    57→  /** Clear all active toasts */
    58→  clearAllToasts: () => void;
    59→  /** Array of currently active toasts */
    60→  toasts: ToastData[];
    61→}
    62→
    63→// Create context with undefined default (will throw error if used outside provider)
    64→const ToastContext = createContext<ToastContextValue | undefined>(undefined);
    65→
    66→// Maximum number of toasts to display at once
    67→const MAX_TOASTS = 5;
    68→// Default auto-dismiss duration
    69→const DEFAULT_DURATION = 4000;
    70→
    71→/**
    72→ * ToastProvider Component
    73→ *
    74→ * Wraps your application to provide toast notification functionality.
    75→ */
    76→export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    77→  const [toasts, setToasts] = useState<ToastData[]>([]);
    78→  // Track auto-dismiss timers for each toast
    79→  const timersRef = useRef<Map<string, NodeJS.Timeout>>(new Map());
    80→
    81→  /**
    82→   * Remove a specific toast by ID
    83→   */
    84→  const removeToast = useCallback((id: string) => {
    85→    // Clear the timer for this toast
    86→    const timer = timersRef.current.get(id);
    87→    if (timer) {
    88→      clearTimeout(timer);
    89→      timersRef.current.delete(id);
    90→    }
    91→
    92→    // Remove from state
    93→    setToasts((prevToasts) => prevToasts.filter((toast) => toast.id !== id));
    94→  }, []);
    95→
    96→  /**
    97→   * Display a new toast notification
    98→   */
    99→  const showToast = useCallback(
   100→    (
   101→      message: string,
   102→      variant: 'success' | 'error' | 'warning' | 'info',
   103→      options?: ShowToastOptions
   104→    ) => {
   105→      const id = crypto.randomUUID();
   106→      const duration = options?.duration ?? DEFAULT_DURATION;
   107→
   108→      const newToast: ToastData = {
   109→        id,
   110→        variant,
   111→        message,
   112→        title: options?.title,
   113→        duration,
   114→      };
   115→
   116→      setToasts((prevToasts) => {
   117→        // Add new toast at the beginning
   118→        const updatedToasts = [newToast, ...prevToasts];
   119→
   120→        // Enforce maximum toast limit (FIFO - remove oldest)
   121→        if (updatedToasts.length > MAX_TOASTS) {
   122→          // Clear timers for removed toasts
   123→          const removedToasts = updatedToasts.slice(MAX_TOASTS);
   124→          removedToasts.forEach((toast) => {
   125→            const timer = timersRef.current.get(toast.id);
   126→            if (timer) {
   127→              clearTimeout(timer);
   128→              timersRef.current.delete(toast.id);
   129→            }
   130→          });
   131→
   132→          return updatedToasts.slice(0, MAX_TOASTS);
   133→        }
   134→
   135→        return updatedToasts;
   136→      });
   137→
   138→      // Set up auto-dismiss timer for this toast
   139→      if (duration > 0) {
   140→        const timer = setTimeout(() => {
   141→          removeToast(id);
   142→        }, duration);
   143→        timersRef.current.set(id, timer);
   144→      }
   145→    },
   146→    [removeToast]
   147→  );
   148→
   149→  /**
   150→   * Clear all active toasts
   151→   */
   152→  const clearAllToasts = useCallback(() => {
   153→    // Clear all timers
   154→    timersRef.current.forEach((timer) => clearTimeout(timer));
   155→    timersRef.current.clear();
   156→
   157→    // Clear all toasts
   158→    setToasts([]);
   159→  }, []);
   160→
   161→  /**
   162→   * Cleanup all timers on component unmount
   163→   */
   164→  useEffect(() => {
   165→    return () => {
   166→      // Clear all timers when component unmounts
   167→      timersRef.current.forEach((timer) => clearTimeout(timer));
   168→      timersRef.current.clear();
   169→    };
   170→  }, []);
   171→
   172→  const contextValue: ToastContextValue = {
   173→    showToast,
   174→    removeToast,
   175→    clearAllToasts,
   176→    toasts,
   177→  };
   178→
   179→  return (
   180→    <ToastContext.Provider value={contextValue}>
   181→      {children}
   182→
   183→      {/* Render ToastContainer with active toasts */}
   184→      {toasts.length > 0 && (
   185→        <ToastContainer>
   186→          {toasts.map((toast) => (
   187→            <Toast
   188→              key={toast.id}
   189→              variant={toast.variant}
   190→              message={toast.message}
   191→              title={toast.title}
   192→              onClose={() => removeToast(toast.id)}
   193→            />
   194→          ))}
   195→        </ToastContainer>
   196→      )}
   197→    </ToastContext.Provider>
   198→  );
   199→};
   200→
   201→/**
   202→ * useToast Hook
   203→ *
   204→ * Access toast notification functionality in any component.
   205→ * Must be used within a ToastProvider.
   206→ *
   207→ * @throws Error if used outside ToastProvider
   208→ *
   209→ * @example
   210→ * ```tsx
   211→ * const { showToast } = useToast();
   212→ *
   213→ * // Show success toast
   214→ * showToast('Product created successfully', 'success');
   215→ *
   216→ * // Show error toast with title
   217→ * showToast('Invalid input', 'error', { title: 'Validation Error' });
   218→ *
   219→ * // Show warning with custom duration
   220→ * showToast('Session expiring soon', 'warning', { duration: 8000 });
   221→ * ```
   222→ */
   223→export const useToast = (): ToastContextValue => {
   224→  const context = useContext(ToastContext);
   225→
   226→  if (context === undefined) {
   227→    throw new Error('useToast must be used within a ToastProvider');
   228→  }
   229→
   230→  return context;
   231→};
   232→

